  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine applies tier discount when not provided', () => {
  const r = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 5);
});

test('addLine returns DISCOUNT_INVALID for invalid discount', () => {
  const r = createInvoice({
