test('createInvoice explicit discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-002', // Standard tier (0%) but explicit 15%
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 15 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 15);
});

test('createInvoice applies tier discounts to multiple lines independently', () => {
  const r = createInvoice({
    customerId: 'C-001', // Gold (5%)
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5); // tier discount
  assert.equal(r.value.lines[1].discountPercent, 10); // explicit discount
  assert.equal(r.value.lines[2].discountPercent, 5); // tier discount
